-- SQL Insert Script for Quotation Management System
-- Target: User ID = 8 (Auto-resolves company_id from `companies` table)
-- Total Items: 324

USE `quotation_managment`;

ALTER TABLE `instruments` ADD COLUMN IF NOT EXISTS `hsn_code` VARCHAR(20) DEFAULT NULL;
ALTER TABLE `instruments` ADD COLUMN IF NOT EXISTS `image_url` VARCHAR(500) DEFAULT NULL;

-- Set target user_id = 8
SET @target_user_id = 8;

-- Find company_id for user_id = 8, or default to 8 if not set
SET @target_company_id = (SELECT company_id FROM companies WHERE user_id = @target_user_id LIMIT 1);
SET @target_company_id = IFNULL(@target_company_id, 8);

